package com.hospital.mes.qc.domain;
import static org.assertj.core.api.Assertions.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.Test;
/** Value rules of the basic-library standard: no approval state, no version, only maintainable fields. */
class QcSpecificationRulesTest {
 @Test void onlyActiveOrInactiveAndNoTransitionApiExists(){assertThat(QcSpecificationRules.status("ACTIVE")).isEqualTo("ACTIVE");assertThat(QcSpecificationRules.status("INACTIVE")).isEqualTo("INACTIVE");assertThat(QcSpecificationRules.status(null)).isNull();for(String s:List.of("DRAFT","APPROVED","RETIRED","active"))assertThatThrownBy(()->QcSpecificationRules.status(s)).hasMessageContaining("Unknown standard status");assertThatThrownBy(()->QcSpecificationRules.class.getDeclaredMethod("transition",String.class,String.class)).isInstanceOf(NoSuchMethodException.class);}
 @Test void basisTypeIsAClosedListAndTheReferenceIsMandatory(){for(String b:QcSpecificationRules.BASIS_TYPES)assertThat(QcSpecificationRules.basisType(b)).isEqualTo(b);assertThatThrownBy(()->QcSpecificationRules.basisType("PAPER")).hasMessageContaining("Unknown standard basis type");assertThatThrownBy(()->QcSpecificationRules.text(null,300)).hasMessageContaining("Nonblank");}
 @Test void numericBoundsAreInclusiveAndMissingValueNeverPasses(){var i=item("NUMERIC","1","3","9",null);QcSpecificationRules.validateItems(List.of(i));assertThat(QcSpecificationRules.numericPass(i,new BigDecimal("1"))).isTrue();assertThat(QcSpecificationRules.numericPass(i,new BigDecimal("3"))).isTrue();assertThat(QcSpecificationRules.numericPass(i,null)).isFalse();assertThat(QcSpecificationRules.numericPass(i,new BigDecimal("3.1"))).isFalse();}
 @Test void shapePrecisionAndDuplicateCodesFailClosed(){for(var i:List.of(item("NUMERIC",null,null,"9",null),item("NUMERIC","4","2","9",null),item("NUMERIC","0.0000001",null,"9",null),item("NUMERIC","1",null,"9","text"),item("TEXT","1",null,null,"white"),item("TEXT",null,null,null," ")))assertThatThrownBy(()->QcSpecificationRules.validateItems(List.of(i))).isInstanceOf(com.hospital.mes.common.exception.ValidationException.class);var i=item("TEXT",null,null,null,"white powder");QcSpecificationRules.validateItems(List.of(i));assertThatThrownBy(()->QcSpecificationRules.validateItems(List.of(i,i))).hasMessageContaining("Duplicate");}
 @Test void oneSidedBoundsHaveInclusiveEndpointAndMissingValuesNeverPass(){
  for(var i:List.of(item("NUMERIC","1",null,"9",null),item("NUMERIC",null,"1","9",null))){QcSpecificationRules.validateItems(List.of(i));assertThat(QcSpecificationRules.numericPass(i,new BigDecimal("1"))).isTrue();assertThat(QcSpecificationRules.numericPass(i,null)).isFalse();}
  assertThat(QcSpecificationRules.numericPass(item("NUMERIC","1",null,"9",null),new BigDecimal("0.999999"))).isFalse();assertThat(QcSpecificationRules.numericPass(item("NUMERIC",null,"1","9",null),new BigDecimal("1.000001"))).isFalse();
 }
 @Test void strictLockAndSubjectIdentityIds(){assertThat(QcSpecificationRules.expected("\"2\"",2L)).isEqualTo(2);assertThatThrownBy(()->QcSpecificationRules.expected("2",2L)).hasMessageContaining("quoted");assertThatThrownBy(()->QcSpecificationRules.expected("\"2\"",1L)).hasMessageContaining("match");assertThat(QcSpecificationRules.ids(List.of("3","1","3"),"Materials",500)).containsExactly(3L,1L);assertThatThrownBy(()->QcSpecificationRules.ids(List.of("0"),"Materials",500)).hasMessageContaining("Positive decimal");}
 @Test void unknownAndReadOnlyFieldsAreRejectedWithPermissiveGlobalMapper() throws Exception {var mapper=new com.fasterxml.jackson.databind.ObjectMapper().disable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);assertThatThrownBy(()->mapper.readValue("{\"specificationCode\":\"A\",\"versionNoBusiness\":3}",QcCommands.Create.class)).hasMessageContaining("Unknown field");assertThatThrownBy(()->mapper.readValue("{\"itemCode\":\"A\",\"specificationItemId\":\"7\"}",QcCommands.Item.class)).hasMessageContaining("Unknown field");assertThatThrownBy(()->mapper.readValue("{\"recordVersion\":1,\"reason\":\"r\",\"approvalSignatureId\":\"9\"}",QcCommands.Remove.class)).hasMessageContaining("Unknown field");}
 private QcCommands.Item item(String type,String lo,String hi,String unit,String text){return new QcCommands.Item("ASSAY","Assay",true,type,lo,hi,unit,text,"M1","1");}
}
